#include <cmath>
#include <algorithm>
#include <stack>
#include <queue>
#include <vector>

using namespace std;

int* dp;

void func(int N, int C) {
    int beat[N][16], push[C][16];
    int maximum = 0;

    for (int i = 0; i < N; i++) {
        for (int k = 0; k < 16; k++) scanf("%d", &beat[i][k]);
    }

    for (int i = 0; i < C; i++) {
        for (int k = 0; k < 16; k++) scanf("%d", &push[i][k]);
    }

    int tmp, S, code;
    int work[C][16];
    S = 1;
    code = 0;
    for (int i = 0; i < 16; i++) {
        code += S * beat[0][i];
        S *= 2;
    }
    dp[1 * 65536 + code] = 0;

    for (int k = 0; k < C; k++) {
        tmp = 0;
        for (int p = 0; p < 16; p++) {
            work[k][p] = beat[0][p];
            if (work[k][p] == 1) {
                if (push[k][p] == 1) {
                    work[k][p] = 0;
                    tmp++;
                }
            }
        }

        S = 1;
        code = 0;
        for (int i = 0; i < 16; i++) {
            code += S * work[k][i];
            S *= 2;
        }
        dp[1 * 65536 + code] = max(dp[1 * 65536 + code], tmp);
        maximum = max(maximum, dp[1 * 65536 + code]);
    }

    for (int i = 1; i < N; i++) {
        for (int state = 0; state < 65536; state++) {
            if (dp[i * 65536 + state] != -1) {
                S = 1;
                code = 0;
                for (int loop = 0; loop < 16; loop++) {
                    if (state & (1 << loop)) {
                        code += S;
                    } else {
                        code += S * beat[i][loop];
                    }
                    S *= 2;
                }
                dp[(i + 1) * 65536 + code] = max(dp[(i + 1) * 65536 + code], dp[i * 65536 + state]);

                for (int k = 0; k < C; k++) {
                    tmp = 0;
                    for (int p = 0; p < 16; p++) {
                        if (state & (1 << p)) {
                            if (push[k][p] == 1) {
                                work[k][p] = 0;
                                tmp++;
                            } else {
                                work[k][p] = 1;
                            }
                        } else {
                            work[k][p] = beat[i][p];
                            if (work[k][p] == 1) {
                                if (push[k][p] == 1) {
                                    work[k][p] = 0;
                                    tmp++;
                                }
                            }
                        }
                    }

                    S = 1;
                    code = 0;
                    for (int a = 0; a < 16; a++) {
                        code += S * work[k][a];
                        S *= 2;
                    }
                    dp[(i + 1) * 65536 + code] = max(dp[(i + 1) * 65536 + code], tmp + dp[i * 65536 + state]);
                }
            }
        }
    }

    for (int i = 0; i < 65536; i++) maximum = max(maximum, dp[N * 65536 + i]);
    printf("%d\n", maximum);
}

int main() {
    int N, C;
    dp = new int[31 * 65536];  // Allocate a 1D array for dp

    while (true) {
        scanf("%d %d", &N, &C);
        if (N == 0 && C == 0) break;

        fill(dp, dp + 31 * 65536, -1); // Efficiently initialize dp array with -1

        func(N, C);
    }

    delete[] dp; // Clean up
    return 0;
}

